// Round ("Original" / Gen 1) dish, converted from Round Starlink Assembled.obj —
// a 589 mm circular reflector on a mast with a base foot,
// 457 mm from the dish face down to the foot.
//
// The one model here with a motor. The kickstand dishes are rigid bodies that
// lean as a whole; this one hinges, so it carries a `joint`: the dish head tilts
// to the boresight at the neck while the mast stays upright on its foot, which is
// how the hardware actually moves. The pivot is measured, not guessed — the neck
// barrel is a cylinder lying along x, so the head swings in the y-z plane.
//
// Real tilt travel is roughly 14-45 deg off vertical, which is where ordinary
// Starlink boresight elevations (about 45-76 deg) put it. Nothing clamps to that
// range: the dish aims at the true boresight so it stays with its beam.
//
// Same reduction as the Standard: coincident weld (lossless — it is what stops the
// CAD patch borders tearing) then quadric edge collapse, run on each solid alone
// so the visible reflector keeps its budget. Stored as int16 SIXTY-FOURTHS of a
// millimetre (the ~450 mm mast overflows hundredths).
import type { DishModelMesh } from "./types";
export const rev2CircularDish: DishModelMesh = {
  scale: 64,
  longAxisMm: 590,
  // reflector face, its dark edge ribbon, the neck barrel — then the mast and
  // the foot, which do not tilt.
  parts: [
    [0, 2351, 0.95],
    [2351, 449, 0.4],
    [2800, 300, 0.4],
    [3100, 1200, 0.4],
    [4300, 1000, 0.4],
  ],
  joint: { baseVertex: 1552, pivot: [0, 0, -3046] },
  positions:
    "",
  indices:
    "",
};
